pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        // If maxsplit == 0, or string is empty, no splitting is performed.
        if maxsplit == 0 || s.is_empty() {
            out.push(vec![s]);
            continue;
        }

        // Collect from the right, at most maxsplit splits => at most maxsplit+1 parts.
        let mut parts: Vec<String> = s
            .rsplitn((maxsplit as usize) + 1, &sep)
            .map(|p| p.to_string())
            .collect();

        // rsplitn yields from right to left; reverse to get left-to-right order.
        parts.reverse();

        // Ensure each inner list is non-empty (rsplitn always yields at least one part).
        if parts.is_empty() {
            parts.push(String::new());
        }

        out.push(parts);
    }

    out
}